(11862,'a0c38cd7-12a0-40e5-892d-8494b4c7bb52','a0c38cd7-1cef-400a-99cf-cac989b5411e',NULL,1,'query','{\"connection\":\"mariadb\",\"bindings\":[],\"sql\":\"insert into `remarks` (`label`, `description`, `type`, `status_id`, `created_by`, `updated_by`, `updated_at`, `created_at`) values (\'Cas 3 : suivi des travaux\', \'\\\\n                                <p>Veuillez nous contacter d\\u00e8s l\\u2019entame des travaux.\\\\n                                <br>Nous tenons \\u00e0 pr\\u00e9ciser que l\\u2019ex\\u00e9cution compl\\u00e8te de tout travail de carrosserie sans informer l\\u2019expert pour le suivi peut entrainer la non prise en charge des pi\\u00e8ces remplac\\u00e9es comme pi\\u00e8ces neuves.<\\/p>\\\\n                            \', \'work-sheet\', 1, 1, 1, \'2026-01-05 12:50:19\', \'2026-01-05 12:50:19\')\",\"time\":\"0.05\",\"slow\":false,\"file\":\"\\/var\\/www\\/html\\/database\\/seeders\\/RemarkSeeder.php\",\"line\":48,\"hash\":\"5f278255349f85550a857a9368f4ec20\",\"hostname\":\"e-expert-back-web\"}','2026-01-05 12:50:19'),
